<template><AdminLayout><div class="management-page community-admin">
  <header><h1>Quản trị cộng đồng</h1><p>Tiếp nhận báo cáo, giữ thảo luận an toàn và ghi nhận quyết định minh bạch.</p><RouterLink class="button button-primary" to="/community/create?type=ANNOUNCEMENT">Đăng thông báo chính thức</RouterLink></header>
  <nav class="community-admin-tabs" aria-label="Khu vực quản trị cộng đồng"><RouterLink v-for="(label,key) in views" :key="key" :to="{path:'/admin/community',query:{view:key}}" :aria-current="view===key?'page':undefined">{{ label }}</RouterLink></nav>
  <form class="management-toolbar" @submit.prevent="filter"><div><label for="community-admin-status">Trạng thái</label><select id="community-admin-status" v-model="statusInput" :disabled="busy"><option v-for="key in statuses" :key="key" :value="key">{{ labels[key] }}</option></select></div><div v-if="view!=='reports'"><label for="community-admin-search">Tìm tiêu đề hoặc nội dung</label><input id="community-admin-search" v-model="searchInput" maxlength="160" type="search" :disabled="busy"/></div><button class="button button-outline" :disabled="busy||loading">Lọc nội dung</button><button type="button" class="button button-outline" :disabled="busy||loading" @click="load">Tải lại</button></form>
  <p v-if="error" role="alert">{{ error }}</p><p v-if="success" role="status">{{ success }}</p>
  <ManagementTable :caption="views[view]" :columns="columns" :rows="data.content" :loading="loading" :error="listError" empty-title="Không có nội dung ở bộ lọc này." @retry="load"><template #target="{row}"><strong>{{ view==='reports'?(row.targetType==='COMMUNITY_POST'?'Bài viết #':'Bình luận #')+row.targetId:row.title }}</strong><small v-if="view!=='reports'">{{ row.authorName }} · {{ labelFor(roleLabels,row.authorRole,'Thành viên') }}</small></template><template #context="{row}">{{ view==='reports'?(labelFor(reasons,row.reason,'Lý do cần xem xét')):preview(row.body) }}</template><template #status="{row}"><span class="management-status">{{ labelFor(labels,row.status,'Trạng thái cần kiểm tra') }}</span></template><template #submitted="{row}"><time :datetime="row.createdAt">{{ dateTimeLabel(row.createdAt) }}</time></template><template #actions="{row}"><button type="button" class="button button-outline" :disabled="busy" :aria-label="'Xem nội dung #'+row.id" @click="select(row)">Xem chi tiết</button></template></ManagementTable>
  <ManagementPagination v-if="!listError" :page="data.page" :size="data.size" :total-pages="data.totalPages" :total-elements="data.totalElements" :count="data.content.length" noun="nội dung" :loading="loading" :busy="busy"/>
  <section v-if="selected" class="management-secondary community-moderation-detail" aria-labelledby="community-case-heading"><h2 id="community-case-heading" tabindex="-1">{{ selected.kind==='POST'?'Bài viết':'Bình luận' }} được xem xét</h2><p><strong>{{ selected.authorName }}</strong> · {{ labelFor(roleLabels,selected.authorRole,'Thành viên') }} · {{ labelFor(labels,selected.status,'Trạng thái cần kiểm tra') }}<span v-if="selected.parentStatus!=='PUBLIC'"> · Bài cha {{ labelFor(labels,selected.parentStatus,'Trạng thái cần kiểm tra') }}</span></p><h3>{{ selected.title }}</h3><p class="community-admin-body">{{ selected.body }}</p><RouterLink :to="'/community/posts/'+selected.postId">Mở bài công khai (có thể không còn hiển thị)</RouterLink>
    <section v-if="report" class="community-report-context"><h3>Thông tin báo cáo</h3><p>{{ labelFor(reasons,report.reason,'Lý do cần xem xét') }} · {{ labelFor(labels,report.status,'Trạng thái cần kiểm tra') }}</p><p>{{ report.description||'Không có mô tả bổ sung.' }}</p><p v-if="report.resolution">Quyết định gần nhất: {{ report.resolution }}</p><form v-if="report.status==='OPEN'||report.status==='IN_REVIEW'" class="management-form" @submit.prevent="confirmReport"><label for="community-report-decision">Xử lý báo cáo</label><select id="community-report-decision" v-model="reportDecision" required :disabled="busy"><option value="" disabled>Chọn quyết định</option><option v-if="report.status==='OPEN'" value="IN_REVIEW">Tiếp nhận để xem xét</option><template v-else><option value="RESOLVED">Đã xử lý</option><option value="DISMISSED">Bác bỏ / không đủ cơ sở</option></template></select><label for="community-report-resolution">Lý do quyết định</label><textarea id="community-report-resolution" v-model="reportReason" required maxlength="1000" rows="3" :disabled="busy"/><button class="button button-outline" :disabled="busy">Kiểm tra quyết định báo cáo</button></form><details><summary>Lịch sử xử lý báo cáo</summary><p v-if="reportHistoryError" role="alert">{{ reportHistoryError }}</p><ul v-else><li v-for="entry in reportHistory" :key="entry.id"><strong>{{ entry.actorName }} · {{ entry.actionLabel }}</strong><time :datetime="entry.createdAt"> · {{ dateTimeLabel(entry.createdAt) }}</time><p v-if="entry.reason">Lý do: {{ entry.reason }}</p></li></ul></details></section>
    <form v-if="actions.length" class="management-form" @submit.prevent="confirmModeration"><label for="community-moderation-action">Thao tác với nội dung</label><select id="community-moderation-action" v-model="action" required :disabled="busy"><option value="" disabled>Chọn thao tác kiểm duyệt</option><option v-for="key in actions" :key="key" :value="key">{{ actionLabels[key] }}</option></select><label for="community-moderation-reason">Lý do kiểm duyệt (tối đa 300 ký tự)</label><textarea id="community-moderation-reason" v-model="reason" required maxlength="300" rows="3" :disabled="busy"/><button class="button button-primary" :disabled="busy">Kiểm tra quyết định kiểm duyệt</button></form><p v-else class="community-hint">Nội dung đã gỡ được giữ để đối chiếu lịch sử. Không khôi phục tự động nội dung này.</p>
    <section class="community-audit-history"><h3>Lịch sử kiểm duyệt nội dung</h3><p v-if="historyError" role="alert">{{ historyError }} <button type="button" class="button button-outline" @click="loadHistory">Thử lại</button></p><p v-else-if="!history.content.length">Chưa có quyết định kiểm duyệt.</p><ol v-else><li v-for="entry in history.content" :key="entry.id"><strong>{{ entry.actorName }} · {{ entry.actionLabel }}</strong><time :datetime="entry.createdAt"> · {{ dateTimeLabel(entry.createdAt) }}</time><p>{{ entry.detail.previousState }} → {{ entry.detail.newState }}</p><p v-if="entry.detail.reason">Lý do: {{ entry.detail.reason }}</p></li></ol><nav v-if="history.totalPages>1" class="community-actions" aria-label="Phân trang lịch sử kiểm duyệt"><button type="button" class="button button-outline" :disabled="!historyPage" @click="historyPage--;loadHistory()">Trước</button><button type="button" class="button button-outline" :disabled="historyPage+1>=history.totalPages" @click="historyPage++;loadHistory()">Sau</button></nav></section>
  </section>
  <ConfirmAction ref="confirmation" title="Xác nhận quyết định quản trị" :description="confirmationText" confirm-label="Xác nhận quyết định" :busy="busy" :error="error" @confirm="execute"/>
</div></AdminLayout></template>
<script setup>
import {labelFor,dateTimeLabel} from '../../services/presentation.js';

import {ref,computed,watch,nextTick,onBeforeUnmount} from 'vue';import {useRoute,useRouter} from 'vue-router';import AdminLayout from '../../layouts/AdminLayout.vue';import ManagementTable from '../../components/marketplace/ManagementTable.vue';import ManagementPagination from '../../components/marketplace/ManagementPagination.vue';import ConfirmAction from '../../components/community/ConfirmAction.vue';import {marketplaceRequest as request} from '../../services/marketplace.js';import {preview} from '../../services/discussions.js';import {roleLabels} from '../../services/community.js';import '../../css/community.css';
const route=useRoute(),router=useRouter(),views={posts:'Bài viết',comments:'Bình luận',reports:'Báo cáo vi phạm'},view=computed(()=>String(route.query.view||'posts')),labels={PUBLIC:'Công khai',HIDDEN:'Đã ẩn',REMOVED:'Đã gỡ',OPEN:'Chờ tiếp nhận',IN_REVIEW:'Đang xem xét',RESOLVED:'Đã xử lý',DISMISSED:'Đã bác bỏ'},reasons={SPAM:'Spam/quảng cáo',HARASSMENT:'Quấy rối/xúc phạm',MISLEADING:'Thông tin gây hiểu nhầm',PROHIBITED:'Nội dung không phù hợp',FRAUD:'Dấu hiệu lừa đảo',OTHER:'Lý do khác'},actionLabels={HIDE:'Ẩn nội dung',REMOVE:'Gỡ nội dung',RESTORE:'Khôi phục nội dung đã ẩn',PIN:'Ghim hướng dẫn/thông báo',UNPIN:'Bỏ ghim',LOCK:'Đóng thảo luận',UNLOCK:'Mở lại thảo luận'};
const statuses=computed(()=>view.value==='reports'?['OPEN','IN_REVIEW','RESOLVED','DISMISSED']:['PUBLIC','HIDDEN','REMOVED']),statusInput=ref('PUBLIC'),searchInput=ref(''),data=ref({content:[],page:0,size:10,totalPages:0,totalElements:0}),loading=ref(false),listError=ref(''),busy=ref(false),error=ref(''),success=ref(''),selected=ref(null),report=ref(null),action=ref(''),reason=ref(''),reportDecision=ref(''),reportReason=ref(''),history=ref({content:[],totalPages:0}),historyPage=ref(0),historyError=ref(''),reportHistory=ref([]),reportHistoryError=ref(''),confirmation=ref(null),confirmationText=ref('');let generation=0,selectionGeneration=0,pending=null,listUrl='';
const columns=[{key:'target',label:'Nội dung'},{key:'context',label:'Ngữ cảnh'},{key:'status',label:'Trạng thái'},{key:'submitted',label:'Ngày gửi'},{key:'actions',label:'Thao tác'}];
const actions=computed(()=>!selected.value?[]:selected.value.status==='REMOVED'?[]:selected.value.status==='HIDDEN'?['RESTORE','REMOVE']:['HIDE','REMOVE',...(selected.value.kind==='POST'?[selected.value.pinned?'UNPIN':'PIN',selected.value.locked?'UNLOCK':'LOCK']:[])]);
function filter(){router.push({path:'/admin/community',query:{view:view.value,status:statusInput.value,...(searchInput.value.trim()?{search:searchInput.value.trim()}:{})}});}
async function load(){const ticket=++generation;loading.value=true;listError.value='';selected.value=null;selectionGeneration++;error.value='';if(!views[view.value]){listError.value='Bộ lọc quản trị không hợp lệ.';loading.value=false;return;}statusInput.value=String(route.query.status||statuses.value[0]);searchInput.value=String(route.query.search||'');const params=new URLSearchParams({status:statusInput.value,page:String(route.query.page||0)});if(view.value!=='reports'){params.set('kind',view.value==='posts'?'POST':'COMMENT');if(searchInput.value)params.set('search',searchInput.value);}try{listUrl='/admin/community/'+(view.value==='reports'?'reports':'content')+'?'+params;const result=await request(listUrl);if(ticket===generation){if(result.totalPages>0&&result.page>=result.totalPages){await router.replace({path:route.path,query:{...route.query,page:String(result.totalPages-1)}});return;}data.value=result;}}catch(e){if(ticket===generation)listError.value=e.message;}finally{if(ticket===generation)loading.value=false;}}
async function select(row){const ticket=++selectionGeneration;error.value='';success.value='';selected.value=null;report.value=view.value==='reports'?row:null;history.value={content:[],totalPages:0};historyPage.value=0;action.value='';reason.value='';reportDecision.value='';reportReason.value='';reportHistory.value=[];reportHistoryError.value='';const kind=view.value==='reports'?(row.targetType==='COMMUNITY_POST'?'POST':'COMMENT'):row.kind,id=view.value==='reports'?row.targetId:row.id;try{const result=await request('/admin/community/content/'+kind+'/'+id);if(ticket!==selectionGeneration)return;selected.value=result;await nextTick();document.getElementById('community-case-heading')?.focus();await loadHistory();if(report.value){try{const entries=await request('/admin/community/reports/'+report.value.id+'/history');if(ticket===selectionGeneration)reportHistory.value=entries.content;}catch(e){if(ticket===selectionGeneration)reportHistoryError.value=e.message;}}}catch(e){if(ticket===selectionGeneration)error.value=e.message;}}
async function loadHistory(){if(!selected.value)return;const ticket=selectionGeneration;historyError.value='';try{const result=await request('/admin/community/content/'+selected.value.kind+'/'+selected.value.id+'/history?page='+historyPage.value);if(ticket===selectionGeneration)history.value=result;}catch(e){if(ticket===selectionGeneration)historyError.value=e.message;}}
function confirmModeration(){if(busy.value)return;pending='content';confirmationText.value=actionLabels[action.value]+' #'+selected.value.id+'. Lý do: '+reason.value;error.value='';confirmation.value.open();}
function confirmReport(){if(busy.value)return;pending='report';confirmationText.value='Chuyển báo cáo #'+report.value.id+' sang '+labels[reportDecision.value]+'. Lý do: '+reportReason.value;error.value='';confirmation.value.open();}
async function execute(){if(busy.value)return;busy.value=true;error.value='';const ticket=selectionGeneration;try{if(pending==='content'){const result=await request('/admin/community/content/'+selected.value.kind+'/'+selected.value.id,'PATCH',{action:action.value,reason:reason.value,revision:selected.value.revision});if(ticket!==selectionGeneration)return;selected.value=result;action.value='';reason.value='';historyPage.value=0;await loadHistory();}else{const result=await request('/admin/reports/'+report.value.id,'PATCH',{status:reportDecision.value,reason:reportReason.value,revision:report.value.revision});if(ticket!==selectionGeneration)return;report.value=result;reportDecision.value='';reportReason.value='';reportHistory.value=(await request('/admin/community/reports/'+report.value.id+'/history')).content;}success.value='Đã lưu quyết định và lịch sử tại máy chủ.';confirmation.value.close();try{const current=await request(listUrl);if(ticket===selectionGeneration)data.value=current;}catch(e){listError.value=e.message;}}catch(e){if(ticket===selectionGeneration)error.value=e.message;}finally{busy.value=false;}}
watch(()=>route.fullPath,load,{immediate:true});onBeforeUnmount(()=>{generation++;selectionGeneration++;});
</script>
